# Prefix/suffix search: a trie for prefixes, a reversed trie for suffixes.
words = ['archive','archives','archival','archiving','index','catalog']
def build_trie(ws, rev=False):
    root = {}
    for w in ws:
        node = root
        for ch in (w[::-1] if rev else w):
            node = node.setdefault(ch, {})
        node["$"] = w
    return root
def collect(node, out):
    for k, v in node.items():
        if k == "$": out.append(v)
        else: collect(v, out)
def search(trie, key):
    node = trie
    for ch in key:
        if ch not in node: return []
        node = node[ch]
    out = []; collect(node, out); return sorted(out)
trie, rtrie = build_trie(words), build_trie(words, rev=True)
print("prefix 'arch':", search(trie, "arch"))
print("suffix 'ing':", search(rtrie, "ing"[::-1]))

